package kz.structure.reminder;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;
public class AlarmReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){int s=i.getIntExtra("stage",2),id=i.getIntExtra("id",0);String channel="alarm_v3_"+s;NotificationManager nm=c.getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel(channel,s==6?"За 6 часов":"За 2 часа",NotificationManager.IMPORTANCE_HIGH);ch.setSound(Uri.parse("android.resource://"+c.getPackageName()+"/raw/signal"+s),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());ch.enableVibration(true);ch.setVibrationPattern(s==6?new long[]{0,280,270,280}:new long[]{0,280,270,280,270,280});nm.createNotificationChannel(ch);Intent a=new Intent(c,MainActivity.class).putExtras(i).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent p=PendingIntent.getActivity(c,id,a,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("До встречи "+(s==6?"6 часов":"2 часа")).setContentText(i.getStringExtra("partner")).setStyle(new Notification.BigTextStyle().bigText(new java.text.SimpleDateFormat("HH:mm · dd.MM.yyyy",java.util.Locale.getDefault()).format(new java.util.Date(i.getLongExtra("meeting",0)))+"\n"+i.getStringExtra("partner"))).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setContentIntent(p).setFullScreenIntent(p,true).setAutoCancel(true).build();nm.notify(id,n);}}